import fs from "fs";
import path from "path";
import os from "os";
const M = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");
const pathBad =
  /[ãõáéíóúç]|formato_do|formatacao|padronizacao|barra_de|encapsulamento|sobrescrita|menu_de|botao_de|coluna_de|componente_de|roteamento|separacao|alinhamento|consulta de|layout de|contêiner|correto do|chave v for|margem inferior|tecnologia |^\.md$/i;
const bodyBad =
  /Defeito técnico|Padrão técnico|Bug conhecido|Antes de fundir|Sessão de origem|Formato do corpo|Menu de diálogo|no diretório|dos quais|concluíram|substituído|evidência:|descrição:|causa raiz|verificação e origem|Tratar acessibilidade|Alterar itens|Centralizar a/i;
const dirs = [];
const files = [];
const meta = [];
function walk(x) {
  for (const e of fs.readdirSync(x, { withFileTypes: true })) {
    const p = path.join(x, e.name);
    const rel = path.relative(M, p).replace(/\\/g, "/");
    if (e.isDirectory()) {
      if (/[ãõáéíóúç]|^tecnologia /i.test(e.name)) dirs.push(rel);
      walk(p);
    } else if (e.name.endsWith(".md") && !e.name.startsWith(".")) {
      if (pathBad.test(rel) || e.name === ".md") files.push(rel);
      const raw = fs.readFileSync(p, "utf8");
      if (bodyBad.test(raw)) meta.push(rel);
    }
  }
}
walk(M);
let total = 0;
function count(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    if (e.isDirectory()) count(path.join(d, e.name));
    else if (e.name.endsWith(".md") && !e.name.startsWith(".")) total++;
  }
}
count(M);
console.log(JSON.stringify({ totalMd: total, ptDirs: dirs.length, ptPaths: files.length, ptBodyOrMeta: meta.length, samplePaths: files.slice(0, 12), sampleMeta: meta.slice(0, 12) }, null, 2));

import fs from "fs";
import path from "path";
import os from "os";
const MEM = path.join(os.homedir(), ".openviking/data/viking/default/user/default/memories");
const PT = /[ãõáéíóúç]|\b(Registrar|Correção|migração|No diretório|Em 20|Arquivos envolvidos|Origem:|sessão|substituído|concluíram|foi identificado|foi corrigido|Causa raiz|decidiu-se|Foi adicionado|documentou a)\b/i;
const keys = ["event_name", "goal", "summary", "category", "topic"];
async function tr(s) {
  const r = await fetch("http://127.0.0.1:3425/v1/chat/completions", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "auto/hy3",
      temperature: 0,
      max_tokens: 512,
      messages: [
        { role: "system", content: "译成简体中文，只输出译文，保留日期、路径、UUID、英文标识符。" },
        { role: "user", content: s },
      ],
    }),
  });
  const j = await r.json();
  return (j.choices?.[0]?.message?.content || "").trim();
}
const files = [];
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.name.endsWith(".md")) files.push(p);
  }
}
walk(MEM);
let n = 0;
for (const abs of files) {
  let raw = fs.readFileSync(abs, "utf8");
  const m = raw.match(/<!-- MEMORY_FIELDS\s*([\s\S]*?)-->/);
  if (!m) continue;
  let j;
  try {
    j = JSON.parse(m[1].trim());
  } catch {
    continue;
  }
  let changed = false;
  for (const k of keys) {
    if (typeof j[k] === "string" && PT.test(j[k])) {
      j[k] = await tr(j[k]);
      changed = true;
    }
  }
  if (!changed) continue;
  const block = `<!-- MEMORY_FIELDS\n${JSON.stringify(j, null, 2)}\n-->`;
  raw = raw.replace(/<!-- MEMORY_FIELDS[\s\S]*?-->/, block);
  fs.writeFileSync(abs, raw, "utf8");
  n++;
  console.log("patched", path.relative(MEM, abs));
}
console.log("DONE", n);

