51: // Cursor slugs are a lossy encoding of the workspace path:
52: //   d-repository-V3            -> D:\repository\V3
53: //   d-repository-苏州市房地产监测V3 -> D:\repository\苏州市房地产监测V3
54: // Path segments are joined by "-", and the drive prefix is a single letter.
55: // Hyphens inside real names are indistinguishable, so we re-join everything
56: // after the drive and treat the tail as the project name rather than guessing.
57: function projectFromCursorSlug(slug) {
58:   if (!slug) return "";
59:   const parts = slug.split("-");
60:   if (parts.length < 2) return slug;
61:   const drive = parts[0];
