64:   // Names that were hyphenated get split, so rejoin trailing numeric/alpha shards.
65:   let leaf = rest[rest.length - 1] || "";
66:   // Recover "V3", "2.0", "iHome2-0" style tails that contain hyphens.
67:   for (let i = rest.length - 2; i >= 1; i--) {
68:     const prev = rest[i];
69:     if (/^(repository|Desktop|Downloads|Users|admin)$/i.test(prev)) break;
70:     // only rejoin when the shard looks like a continuation (digits, version, short)
71:     if (/^(\d+|v\d+|\d\.\d+|[A-Za-z]{1,3})$/i.test(prev) && leaf.length <= 12) {
72:       leaf = prev + "-" + leaf;
73:     } else break;
74:   }
75:   if (!leaf) leaf = slug;
76:   return leaf;
77: }
