10: const BASE = path.join(HOME, "Documents/deepseek-harness/default-workspace/memory-migration");
11: const OUT = path.join(BASE, "out");
12: const NODE = process.execPath;
13: 
14: const bRoot = path.join(OUT, "bundles");
15: const projects = fs.readdirSync(bRoot).filter((d) => fs.statSync(path.join(bRoot, d)).isDirectory()).sort();
16: 
17: const log = [];
18: console.error(`Distilling ${projects.length} projects…`);
19: let nFiles = 0, nMem = 0, nSkip = 0, nDup = 0;
20: for (const p of projects) {
21:   const t0 = Date.now();
22:   const r = spawnSync(NODE, [path.join(BASE, "scripts/distill-draft.mjs"), p], {
23:     cwd: BASE, encoding: "utf8", timeout: 300000,
24:   });
25:   if (r.status !== 0) {
26:     console.error(`  ✗ ${p}: ${(r.stderr || "").split("\n").slice(-3).join(" | ")}`);
27:     log.push({ project: p, ok: false, err: (r.stderr || "").slice(-200) });
28:     continue;
29:   }
30:   try {
31:     const out = JSON.parse(r.stdout);
32:     nFiles += out.bundles || 0; nMem += out.kept || 0; nSkip += out.skipped || 0; nDup += out.dup || 0;
33:     log.push({ project: p, ok: true, bundles: out.bundles || 0, kept: out.kept || 0, skipped: out.skipped || 0, dup: out.dup || 0 });
34:   } catch (e) {
35:     log.push({ project: p, ok: true, raw: r.stdout.slice(-200) });
36:   }
37: }
38: fs.writeFileSync(path.join(OUT, "distill-all-log.json"), JSON.stringify({ total: projects.length, nFiles, nMem, nSkip, nDup, log }, null, 2), "utf8");
